_SECRET_MAP = {"did": "DID_API_KEY", "heygen": "HEYGEN_API_KEY"}

def _apply_secret_overlay(cfg):
    sec = _read_secrets()
    for prov, envk in _SECRET_MAP.items():
        if prov in cfg.get("cloud_apis", {}) and sec.get(envk):
            cfg["cloud_apis"][prov]["api_key"] = sec[envk]
    return cfg

def save_studio_config(cfg):
    out = copy.deepcopy(cfg)
    # Strip cloud API keys before persisting — they belong in secrets/env only.
    for prov in _SECRET_MAP:
        if prov in out.get("cloud_apis", {}):
            out["cloud_apis"][prov]["api_key"] = ""
    with open(STUDIO_CONFIG_FILE, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=2, ensure_ascii=False)

def get_engine_choices():
    choices = ["LivePortrait", "Hallo2"]
    cfg = load_studio_config()
    if cfg["cloud_apis"]["heygen"].get("api_key") and cfg["cloud_apis"]["heygen"].get("enabled"):
        choices.append("HeyGen (Cloud)")
    if cfg["cloud_apis"]["did"].get("api_key") and cfg["cloud_apis"]["did"].get("enabled"):
        choices.append("D-ID (Cloud)")
    if cfg["open_source"]["musetalk"].get("enabled"):
        choices.append("MuseTalk (Real-time)")
    if cfg["open_source"]["sadtalker"].get("enabled"):
        choices.append("SadTalker")
    if cfg["open_source"]["wav2lip"].get("enabled"):
        choices.append("Wav2Lip")
    return choices

