def to_wsl_path(p, quote=False):
    p = str(p).replace("\\", "/")
    if len(p) > 1 and p[1] == ":":
        drive = p[0].lower()
        p = f"/mnt/{drive}/{p[3:]}"
    return f"'{p}'" if quote else p

def split_script(full_script, mode, max_minutes, default_char_slug,
                 default_char_name, all_chars, default_language):
    if mode == "manual":
        return parse_manual_script(full_script, default_char_slug,
                                   default_char_name, all_chars, default_language)
    if mode in ("ai", "hybrid"):
        scenes = split_with_ai(full_script, max_minutes, default_char_slug,
                               default_char_name, all_chars, default_language)
        if scenes:
            return scenes
    return _rule_split(full_script, max_minutes, default_char_slug,
                       default_char_name, default_language)
